// Original — Frictionborn Motion
"use client";

import { useEffect, useRef, useCallback } from "react";
import { createSurface, type Surface } from "@frictionborn/runtime/gl";
import { useFrame, useFrameGuard, usePaused } from "@frictionborn/runtime";
import { vertexShaderSource, fragmentShaderSource } from "./distortion-image.glsl";

declare const process: any;

export interface DistortionImageGLProps {
  imageElement: HTMLImageElement | null;
  pointerPos: { x: number; y: number }; // Normalized [0, 1] relative to image dimensions
  isHovered: boolean;
  strength?: number;
  speed?: number;
  tier?: number;
  onContextLost?: () => void;
  onContextRestored?: () => void;
  onDowngrade?: () => void;
  onTaintedCORS?: () => void;
}

export default function DistortionImageGL({
  imageElement,
  pointerPos,
  isHovered,
  strength = 0.25,
  speed = 1.0,
  tier = 3,
  onContextLost,
  onContextRestored,
  onDowngrade,
  onTaintedCORS,
}: DistortionImageGLProps) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const surfaceRef = useRef<Surface | null>(null);
  const programRef = useRef<WebGLProgram | null>(null);
  const textureRef = useRef<WebGLTexture | null>(null);
  const glRef = useRef<WebGL2RenderingContext | null>(null);

  const uniformsRef = useRef<{
    resolution?: WebGLUniformLocation;
    mouse?: WebGLUniformLocation;
    time?: WebGLUniformLocation;
    progress?: WebGLUniformLocation;
    strength?: WebGLUniformLocation;
    speed?: WebGLUniformLocation;
    image?: WebGLUniformLocation;
  }>({});

  const timeRef = useRef<number>(0);
  const progressRef = useRef<number>(0);
  const pointerPosRef = useRef(pointerPos);
  pointerPosRef.current = pointerPos;
  const isHoveredRef = useRef(isHovered);
  isHoveredRef.current = isHovered;

  const paused = usePaused(); // @frictionborn-guard

  const maxDpr = tier >= 3 ? 2.0 : 1.5;
  const renderScale = tier >= 3 ? 1.0 : 0.75;
  const maxTextureDim = tier >= 3 ? 2048 : 1024;

  const onContextLostRef = useRef(onContextLost);
  onContextLostRef.current = onContextLost;
  const onContextRestoredRef = useRef(onContextRestored);
  onContextRestoredRef.current = onContextRestored;
  const onDowngradeRef = useRef(onDowngrade);
  onDowngradeRef.current = onDowngrade;
  const onTaintedCORSRef = useRef(onTaintedCORS);
  onTaintedCORSRef.current = onTaintedCORS;

  // Frame guard triggers automatic downgrade if p75 frame times exceed budget
  useFrameGuard({ onDowngrade: () => onDowngradeRef.current?.(), active: !paused }); // @frictionborn-guard

  // Upload texture with tier size cap and CORS taint protection
  const uploadTexture = useCallback(
    (gl: WebGL2RenderingContext, img: HTMLImageElement): boolean => {
      // Clean up any existing texture to prevent memory/texture leaks
      if (textureRef.current) {
        gl.deleteTexture(textureRef.current);
        textureRef.current = null;
      }

      const texture = gl.createTexture();
      if (!texture) return false;

      gl.bindTexture(gl.TEXTURE_2D, texture);

      // Determine upload source: scale down to maxTextureDim if required
      const natW = img.naturalWidth || img.width;
      const natH = img.naturalHeight || img.height;

      if (!natW || !natH) {
        gl.deleteTexture(texture);
        return false;
      }

      let uploadSource: TexImageSource = img;

      if (natW > maxTextureDim || natH > maxTextureDim) {
        const scale = Math.min(maxTextureDim / natW, maxTextureDim / natH);
        const targetW = Math.max(1, Math.round(natW * scale));
        const targetH = Math.max(1, Math.round(natH * scale));

        const offscreen = document.createElement("canvas");
        offscreen.width = targetW;
        offscreen.height = targetH;
        const ctx2d = offscreen.getContext("2d");
        if (!ctx2d) {
          gl.deleteTexture(texture);
          return false;
        }

        try {
          ctx2d.drawImage(img, 0, 0, targetW, targetH);
          uploadSource = offscreen;
        } catch (taintErr) {
          // Canvas drawImage throws SecurityError if tainted
          if (process.env.NODE_ENV !== "production") {
            console.warn(
              "[Frictionborn Motion] DistortionImage: Image is tainted by cross-origin restrictions. Falling back to plain image. Set crossOrigin='anonymous' to enable WebGL distortion.",
              taintErr
            );
          }
          gl.deleteTexture(texture);
          onTaintedCORSRef.current?.();
          return false;
        }
      }

      // Safe texture upload with SecurityError / taint detection
      try {
        gl.texImage2D(
          gl.TEXTURE_2D,
          0,
          gl.RGBA,
          gl.RGBA,
          gl.UNSIGNED_BYTE,
          uploadSource
        );
      } catch (texErr) {
        if (process.env.NODE_ENV !== "production") {
          console.warn(
            "[Frictionborn Motion] DistortionImage: Image is tainted by cross-origin restrictions. Falling back to plain image. Set crossOrigin='anonymous' to enable WebGL distortion.",
            texErr
          );
        }
        gl.deleteTexture(texture);
        onTaintedCORSRef.current?.();
        return false;
      }

      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);

      textureRef.current = texture;
      return true;
    },
    [maxTextureDim]
  );

  const renderFrame = useCallback(() => {
    const surface = surfaceRef.current;
    const program = programRef.current;
    const texture = textureRef.current;
    if (!surface || !program || !texture) return;

    const gl = surface.gl;
    const { resolution, mouse, time, progress, strength: uStrength, speed: uSpeed, image } =
      uniformsRef.current;

    gl.useProgram(program);
    if (resolution) gl.uniform2f(resolution, gl.drawingBufferWidth, gl.drawingBufferHeight);
    if (mouse) gl.uniform2f(mouse, pointerPosRef.current.x, pointerPosRef.current.y);
    if (time) gl.uniform1f(time, timeRef.current);
    if (progress) gl.uniform1f(progress, progressRef.current);
    if (uStrength) gl.uniform1f(uStrength, strength);
    if (uSpeed) gl.uniform1f(uSpeed, speed);
    if (image) {
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, texture);
      gl.uniform1i(image, 0);
    }

    surface.draw();
  }, [strength, speed]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container || !imageElement) return;

    const canvas = document.createElement("canvas");
    canvasRef.current = canvas;
    canvas.setAttribute("aria-hidden", "true");
    Object.assign(canvas.style, {
      position: "absolute",
      inset: "0px",
      width: "100%",
      height: "100%",
      display: "block",
      pointerEvents: "none",
      zIndex: "2",
    });
    container.appendChild(canvas);

    function setupProgram(surface: ReturnType<typeof createSurface>) {
      const gl = surface.gl;
      glRef.current = gl;

      const program = surface.createProgram(vertexShaderSource, fragmentShaderSource);
      programRef.current = program;

      uniformsRef.current = {
        resolution: gl.getUniformLocation(program, "u_resolution") || undefined,
        mouse: gl.getUniformLocation(program, "u_mouse") || undefined,
        time: gl.getUniformLocation(program, "u_time") || undefined,
        progress: gl.getUniformLocation(program, "u_progress") || undefined,
        strength: gl.getUniformLocation(program, "u_strength") || undefined,
        speed: gl.getUniformLocation(program, "u_speed") || undefined,
        image: gl.getUniformLocation(program, "u_image") || undefined,
      };

      if (imageElement) {
        uploadTexture(gl, imageElement);
      }
    }

    try {
      const surface = createSurface(canvas, {
        maxDpr,
        scale: renderScale,
        onContextLost: () => {
          canvas.style.display = "none";
          if (textureRef.current && glRef.current) {
            glRef.current.deleteTexture(textureRef.current);
            textureRef.current = null;
          }
          onContextLostRef.current?.();
        },
        onContextRestored: () => {
          canvas.style.display = "block";
          if (surfaceRef.current) {
            setupProgram(surfaceRef.current);
            renderFrame();
          }
          onContextRestoredRef.current?.();
        },
      }); // @frictionborn-guard

      surfaceRef.current = surface;
      setupProgram(surface);
      renderFrame();
    } catch (err) {
      console.warn("DistortionImage WebGL2 initialization failed; falling back to static image", err);
      if (surfaceRef.current) {
        surfaceRef.current.dispose(); // @frictionborn-guard
        surfaceRef.current = null;
      }
      onContextLostRef.current?.();
    }

    return () => {
      // Explicitly delete WebGL texture to guarantee 0 texture leaks
      if (textureRef.current && glRef.current) {
        glRef.current.deleteTexture(textureRef.current);
        textureRef.current = null;
      }
      if (surfaceRef.current) {
        surfaceRef.current.dispose(); // @frictionborn-guard
        surfaceRef.current = null;
      }
      canvas.remove();
      canvasRef.current = null;
    };
  }, [maxDpr, renderScale, imageElement, uploadTexture, renderFrame]);

  // Frame animation loop managed by runtime useFrame
  useFrame(
    ({ dt }) => {
      const targetProgress = isHoveredRef.current ? 1.0 : 0.0;
      // Exponential smoothing towards target progress (~180ms rise, ~260ms fall)
      const smoothing = isHoveredRef.current ? 0.09 : 0.06;
      progressRef.current += (targetProgress - progressRef.current) * smoothing;

      // Increment animation time while distortion is active
      if (progressRef.current > 0.005) {
        timeRef.current += (dt * 0.001) * speed;
      }

      renderFrame();
    },
    { active: !paused } // @frictionborn-guard
  );

  return (
    <div
      ref={containerRef}
      aria-hidden="true"
      style={{
        position: "absolute",
        inset: 0,
        width: "100%",
        height: "100%",
        overflow: "hidden",
        pointerEvents: "none",
        zIndex: 2,
      }}
    />
  );
}

// Original — Frictionborn Motion DistortionImage shaders
export const vertexShaderSource = `#version 300 es
in vec2 a_position;
out vec2 v_uv;

void main() {
  v_uv = (a_position + 1.0) * 0.5;
  // Flip Y to match standard DOM top-left image orientation
  v_uv.y = 1.0 - v_uv.y;
  gl_Position = vec4(a_position, 0.0, 1.0);
}
`;

export const fragmentShaderSource = `#version 300 es
precision highp float;

// Original — Frictionborn Motion DistortionImage ripple displacement shader
uniform sampler2D u_image;
uniform vec2 u_resolution;
uniform vec2 u_mouse;
uniform float u_time;
uniform float u_progress;
uniform float u_strength;
uniform float u_speed;

in vec2 v_uv;
out vec4 fragColor;

void main() {
  vec2 uv = v_uv;

  // Aspect ratio correction for circular radial ripples rather than stretched ovals
  float aspect = u_resolution.x / max(1.0, u_resolution.y);
  vec2 aspectVec = vec2(aspect, 1.0);

  // Vector from pointer coordinates to current fragment
  vec2 delta = (uv - u_mouse) * aspectVec;
  float dist = length(delta);

  // Radial influence: max impact near pointer, smooth decay to zero
  float radius = 0.60;
  float influence = smoothstep(radius, 0.0, dist);

  // Concentric wave equations modulated by progress and time
  float wave = sin(dist * 26.0 - u_time * u_speed * 4.5) * 0.5 + 0.5;
  float wave2 = cos(dist * 18.0 - u_time * u_speed * 3.0) * 0.5 + 0.5;

  // Directional displacement vector
  vec2 dir = dist > 0.0001 ? normalize(delta / aspectVec) : vec2(0.0);

  // Displacement magnitude scaled by strength and interactive progress
  float dispAmount = wave * wave2 * influence * u_strength * u_progress * 0.07;

  // Subtle chromatic aberration for depth
  vec2 uvR = uv - dir * (dispAmount * 1.15);
  vec2 uvG = uv - dir * dispAmount;
  vec2 uvB = uv - dir * (dispAmount * 0.85);

  // Clamp UVs to avoid edge wrap artifacts
  uvR = clamp(uvR, 0.001, 0.999);
  uvG = clamp(uvG, 0.001, 0.999);
  uvB = clamp(uvB, 0.001, 0.999);

  float r = texture(u_image, uvR).r;
  float g = texture(u_image, uvG).g;
  float b = texture(u_image, uvB).b;
  float a = texture(u_image, uvG).a;

  // Gentle optical highlight along crests
  float highlight = pow(wave, 3.5) * influence * u_progress * 0.06;

  float alpha = clamp(a * u_progress, 0.0, 1.0);
  vec3 rgb = (vec3(r, g, b) + highlight) * alpha;

  fragColor = vec4(rgb, alpha);
}
`;

// Original — Frictionborn Motion
"use client";

import React, { useState, useEffect, useRef, useCallback, Suspense, lazy } from "react";
import {
  useCapability,
  useHydrated,
  useReducedMotion,
  useInView,
  glBudget,
  type Lease,
} from "@frictionborn/runtime";

const DistortionImageGL = lazy(() => import("./distortion-image.gl"));

export interface DistortionImageProps extends React.HTMLAttributes<HTMLDivElement> {
  src: string;
  alt: string;
  width?: number | string;
  height?: number | string;
  strength?: number;
  speed?: number;
  maxTier?: number;
  crossOrigin?: "anonymous" | "use-credentials" | "";
  loading?: "eager" | "lazy";
  decoding?: "async" | "auto" | "sync";
  srcSet?: string;
  sizes?: string;
  imgClassName?: string;
  imgStyle?: React.CSSProperties;
  children?: React.ReactNode;
}

export function DistortionImage({
  src,
  alt,
  width,
  height,
  strength = 0.25,
  speed = 1.0,
  maxTier = 3,
  crossOrigin,
  loading = "lazy",
  decoding = "async",
  srcSet,
  sizes,
  imgClassName = "",
  imgStyle,
  className = "",
  style,
  children,
  ...props
}: DistortionImageProps) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const imgRef = useRef<HTMLImageElement | null>(null);
  const instanceId = useRef("distortion-image-" + Math.random().toString(36).slice(2, 8));
  const leaseRef = useRef<Lease | null>(null);
  const idleTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const hydrated = useHydrated(); // @frictionborn-guard
  const cap = useCapability(); // @frictionborn-guard
  const prefersReduced = useReducedMotion(); // @frictionborn-guard
  const inView = useInView(containerRef); // @frictionborn-guard

  const [hasLease, setHasLease] = useState(false);
  const [needsLease, setNeedsLease] = useState(false);
  const [isHovered, setIsHovered] = useState(false);
  const [pointerPos, setPointerPos] = useState({ x: 0.5, y: 0.5 });
  const [imgLoaded, setImgLoaded] = useState(false);
  const [taintedCORS, setTaintedCORS] = useState(false);
  const [isFinePointer, setIsFinePointer] = useState(false);

  // Detect fine pointer capability (mouse/pen) vs coarse touch
  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return;
    const media = window.matchMedia("(pointer: fine)");
    setIsFinePointer(media.matches);
    const listener = (e: MediaQueryListEvent) => setIsFinePointer(e.matches);
    media.addEventListener("change", listener);
    return () => media.removeEventListener("change", listener);
  }, []);

  const effectiveTier = Math.min(cap.tier, maxTier);

  // Compute pointer coordinates normalized [0, 1] relative to the element bounding box
  const updatePointer = useCallback((e: React.PointerEvent<HTMLDivElement>) => {
    const el = containerRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    if (rect.width > 0 && rect.height > 0) {
      const x = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
      const y = Math.max(0, Math.min(1, (e.clientY - rect.top) / rect.height));
      setPointerPos({ x, y });
    }
  }, []);

  const handlePointerInteraction = useCallback(
    (e: React.PointerEvent<HTMLDivElement>) => {
      if (e.pointerType === "touch") return; // Touch pointers fall back to plain image (0 contexts)
      if (idleTimerRef.current) {
        clearTimeout(idleTimerRef.current);
        idleTimerRef.current = null;
      }
      setIsHovered(true);
      setNeedsLease(true);
      updatePointer(e);
    },
    [updatePointer]
  );

  const handlePointerEnter = handlePointerInteraction;
  const handlePointerMove = handlePointerInteraction;

  const scheduleIdleRelease = useCallback(() => {
    setIsHovered(false);
    if (idleTimerRef.current) {
      clearTimeout(idleTimerRef.current);
    }
    // Release the lease after 3 seconds of idle
    idleTimerRef.current = setTimeout(() => {
      setNeedsLease(false);
    }, 3000);
  }, []);

  const handlePointerLeave = scheduleIdleRelease;
  const handleBlur = scheduleIdleRelease;

  const handleFocus = useCallback(() => {
    if (idleTimerRef.current) {
      clearTimeout(idleTimerRef.current);
      idleTimerRef.current = null;
    }
    setIsHovered(true);
    setNeedsLease(true);
  }, []);

  // When leaving the viewport, immediately release any lease and cancel idle timers
  useEffect(() => {
    if (!inView) {
      if (idleTimerRef.current) {
        clearTimeout(idleTimerRef.current);
        idleTimerRef.current = null;
      }
      setNeedsLease(false);
      setIsHovered(false);
    }
  }, [inView]);

  // Context lease management with S8-11 retry subscription
  useEffect(() => {
    const shouldAcquire =
      hydrated &&
      inView &&
      needsLease &&
      effectiveTier >= 2 &&
      !prefersReduced &&
      isFinePointer &&
      !taintedCORS;

    let unsubscribeBudget: (() => void) | null = null;

    const requestInteractiveLease = () => {
      if (leaseRef.current) return;
      const acquired = glBudget.acquire({
        id: instanceId.current,
        priority: 2, // Active hover has elevated priority over ambient backgrounds
        onEvict: () => {
          leaseRef.current = null;
          setHasLease(false);
        },
      });
      if (acquired) {
        leaseRef.current = acquired;
        setHasLease(true);
      }
    };

    if (shouldAcquire) {
      requestInteractiveLease();
      // S8-11: Subscribe to budget frees so waiting visible items retry lease acquisition
      unsubscribeBudget = glBudget.subscribe(() => {
        if (!leaseRef.current) {
          requestInteractiveLease();
        }
      });
    } else if (leaseRef.current) {
      leaseRef.current.release(); // @frictionborn-guard
      leaseRef.current = null;
      setHasLease(false);
    }

    return () => {
      unsubscribeBudget?.();
      if (leaseRef.current) {
        leaseRef.current.release(); // @frictionborn-guard
        leaseRef.current = null;
        setHasLease(false);
      }
    };
  }, [hydrated, inView, needsLease, effectiveTier, prefersReduced, isFinePointer, taintedCORS]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (idleTimerRef.current) {
        clearTimeout(idleTimerRef.current);
      }
      if (leaseRef.current) {
        leaseRef.current.release(); // @frictionborn-guard
        leaseRef.current = null;
      }
    };
  }, []);

  const markImageReady = useCallback(() => {
    const img = imgRef.current;
    if (!img) return;
    if (typeof img.decode === "function") {
      img.decode().then(
        () => setImgLoaded(true),
        () => setImgLoaded(true)
      );
    } else {
      setImgLoaded(true);
    }
  }, []);

  useEffect(() => {
    if (imgRef.current?.complete) {
      markImageReady();
    }
  }, [src, markImageReady]);

  const handleImageLoad = markImageReady;

  const handleTaintedCORS = useCallback(() => {
    setTaintedCORS(true);
    if (leaseRef.current) {
      leaseRef.current.release(); // @frictionborn-guard
      leaseRef.current = null;
      setHasLease(false);
    }
  }, []);

  const shouldRenderGL =
    hydrated &&
    hasLease &&
    imgLoaded &&
    !taintedCORS &&
    !prefersReduced &&
    isFinePointer &&
    effectiveTier >= 2;

  return (
    <div
      ref={containerRef}
      data-frictionborn-item="distortion-image"
      data-tier={effectiveTier}
      onPointerEnter={handlePointerEnter}
      onPointerMove={handlePointerMove}
      onPointerLeave={handlePointerLeave}
      onFocus={handleFocus}
      onBlur={handleBlur}
      tabIndex={0}
      className={`relative inline-block overflow-hidden focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary ${className}`}
      style={{
        position: "relative",
        display: "inline-block",
        overflow: "hidden",
        width,
        height,
        ...style,
      }}
      {...props}
    >
      {/* Real HTML <img> is always in DOM, defines layout, and provides accessible semantics */}
      <img
        ref={imgRef}
        data-frictionborn-poster=""
        src={src}
        alt={alt}
        width={width}
        height={height}
        loading={loading}
        decoding={decoding}
        crossOrigin={crossOrigin}
        srcSet={srcSet}
        sizes={sizes}
        onLoad={handleImageLoad}
        className={`w-full h-full object-cover block select-none ${imgClassName}`}
        style={{
          width: "100%",
          height: "100%",
          objectFit: "cover",
          display: "block",
          userSelect: "none",
          ...imgStyle,
        }}
      />

      {/* WebGL2 Canvas Overlay: loaded via React.lazy + Suspense only when lease acquired */}
      {shouldRenderGL && (
        <Suspense fallback={null}>
          <DistortionImageGL
            imageElement={imgRef.current}
            pointerPos={pointerPos}
            isHovered={isHovered}
            strength={strength}
            speed={speed}
            tier={effectiveTier}
            onDowngrade={() => {
              if (leaseRef.current) {
                leaseRef.current.release(); // @frictionborn-guard
                leaseRef.current = null;
                setHasLease(false);
              }
            }}
            onTaintedCORS={handleTaintedCORS}
          />
        </Suspense>
      )}

      {children && (
        <div style={{ position: "relative", zIndex: 3, pointerEvents: "auto" }}>
          {children}
        </div>
      )}
    </div>
  );
}
